cd /Users/kristinarash/.claude/jobs/624274f9/tmp/batch-101/drafts && cat > /Users/kristinarash/.claude/jobs/624274f9/tmp/batch-101/helpers/g06/fix.js <<'EOF'
const fs = require("fs");
const dir = process.argv[2];
const load = (id) => JSON.parse(fs.readFileSync(`${dir}/${id}.json`, "utf8"));
const save = (id, j) => fs.writeFileSync(`${dir}/${id}.json`, JSON.stringify(j, null, 1) + "\n");

// Q45: separate Study I across-load CV from Study II test-retest CV
let q45 = load("Q45");
q45.evidenceSummary = "Study I tested 22 young healthy men to failure on the bench press against eight loads from 50% to 85% 1RM, and found a very close relationship between relative velocity loss and the percentage of repetitions performed. This relationship was similar for 50-70% 1RM and progressively greater at 75-85% 1RM. Study II tested 28 physically active sport science students on two maximum-repetition tests at 60% 1RM; the percentage of repetitions performed showed very high absolute reliability (CV 2.1-6.6%), with lower CV as velocity loss increased. Across the eight loads in Study I, the CV for the percentage of repetitions performed for a given velocity loss was 2.7-12.1%. The authors provide prediction equations from velocity loss to the percentage of repetitions performed.";
q45.screeningLimitations = "Only the bench press was tested, in young men with estimated rather than directly tested 1RM. Across-load CVs in Study I reached 12.1% at some velocity-loss levels, above the authors' 10% criterion, so the prediction equations are best seen as estimates.";
q45.paper.findings = "In Study I, velocity loss and the percentage of repetitions performed were closely related for all loads, similar for 50-70% 1RM and progressively greater for 75-85% 1RM. In Study II, test-retest CV for the percentage of repetitions performed was 2.1-6.6%, falling as velocity loss increased. In Study I, the CV across loads for the percentage of repetitions performed ranged from 2.7% to 12.1%, depending on the velocity loss.";
q45.paper.limitations = "Only the bench press was tested. The 1RM was estimated from load-velocity relationships in young men. Study I CVs across loads exceeded the authors' 10% criterion at some velocity-loss levels.";
save("Q45", q45);

// Q49: report the per-limb results and drop the false conflict
let q49 = load("Q49");
q49.evidenceSummary = "Longitudinal study of 44 male athletes tested at 6 and 9 months after anterior cruciate ligament reconstruction with a hamstring tendon or bone-patellar tendon-bone graft. Phase-specific countermovement jump impulse and isokinetic knee strength asymmetries were compared between sessions and graft types with mixed-model ANOVAs. The authors report that knee strength asymmetry improved between 6 and 9 months, and that the concentric CMJ impulse asymmetry fell mainly because the uninvolved limb's concentric impulse decreased. Eccentric deceleration impulse fell in both limbs. Changes in strength asymmetry explained little of the change in impulse asymmetry, and graft type did not change these findings.";
q49.screeningLimitations = "The study is observational with two time points, so it cannot show what caused the changes. The competition level and sport of the athletes are not stated.";
q49.paper.findings = "Knee extension and flexion strength asymmetry improved from 6 to 9 months (extension ES -0.50; flexion ES -0.37), mainly through better performance of the ACL-reconstructed limb. The concentric CMJ impulse asymmetry fell significantly (ES -0.42), driven by a significant reduction in concentric impulse of the uninvolved limb. Eccentric deceleration impulse fell significantly in both the ACL-reconstructed and uninvolved limbs, while its asymmetry did not change significantly. Changes in strength asymmetry explained little of the impulse asymmetry change. IKDC scores rose from 6 to 9 months, and CMJ height changes were trivial to small.";
q49.paper.limitations = "The design is observational with two time points and no control group. The sport and competition level are not stated.";
q49.paper.athleteDev = "After ACL reconstruction, track jump impulse in both legs, not only the asymmetry ratio, since eccentric deceleration impulse fell in both limbs and concentric impulse fell in the uninvolved limb. Do not expect knee strength gains alone to correct jump impulse deficits.";
save("Q49", q49);

// Q46: citation without the running-header page placeholder
let q46 = load("Q46");
q46.paper.citation = "Alt T, Nodler YT, Severin J, Knicker AJ, Strüder HK. Velocity-specific and time-dependent adaptations following a standardized Nordic Hamstring Exercise training. Scand J Med Sci Sports. 2017.";
save("Q46", q46);

// Q47: match the resistance-trained adult samples used elsewhere
let q47 = load("Q47");
q47.populations = ["Adult / Recreational"];
save("Q47", q47);
console.log("ok");
EOF
